const baseLayout = (
  title: string,
  name: string,
  content: string,
  actionLink?: string,
  actionText?: string,
  expiryText?: string,
  code?: string
) => `
    <!DOCTYPE html>
    <html lang="en">
      <head>
        <meta charset="UTF-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1.0" />
        <meta http-equiv="X-UA-Compatible" content="IE=edge" />
        <title>${title} - Techstudio Academy</title>
        <style>
          @import url('https://fonts.googleapis.com/css2?family=Schibsted+Grotesk:wght@400;500;600;700;800&display=swap');

          body {
            font-family: 'Schibsted Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            background-color: #f6f5f1;
            margin: 0;
            padding: 0;
            -webkit-font-smoothing: antialiased;
          }

          .wrapper {
            width: 100%;
            table-layout: fixed;
            background-color: #f6f5f1;
            padding: 48px 0;
          }

          .container {
            width: 100%;
            max-width: 600px;
            background-color: #ffffff;
            margin: 0 auto;
            border-radius: 24px;
            overflow: hidden;
            box-shadow: 0 8px 30px rgba(0, 0, 0, 0.06);
            border: 1px solid #e4f1eb;
          }

          .top-banner {
            height: 8px;
            background: linear-gradient(90deg, #0f6e56 0%, #e4f1eb 50%, #fcd98a 100%);
          }

          .header {
            background-color: #ffffff;
            padding: 32px 40px 20px;
            text-align: left;
          }

          .logo-row {
            display: flex;
            align-items: center;
            justify-content: space-between;
          }

          .event-badge {
            font-size: 11px;
            font-weight: 600;
            color: #0f6e56;
            background-color: #e4f1eb;
            padding: 4px 10px;
            border-radius: 20px;
            letter-spacing: 0.03em;
            text-transform: uppercase;
          }

          .content {
            padding: 32px 40px;
            color: #4a4451;
          }

          .title {
            font-size: 26px;
            font-weight: 700;
            margin-bottom: 20px;
            color: #1c1917;
            letter-spacing: -0.02em;
            line-height: 1.2;
          }

          .greeting {
            font-size: 15px;
            font-weight: 600;
            color: #0f6e56;
            margin-bottom: 12px;
          }

          .text {
            font-size: 15px;
            line-height: 1.7;
            margin-bottom: 28px;
            color: #4a4451;
          }

          .ticket-line {
            border-left: 3px solid #0f6e56;
            padding-left: 16px;
            margin: 24px 0;
            background-color: #e4f1eb;
            padding: 16px 20px;
            border-radius: 12px;
            border-left: 4px solid #0f6e56;
          }

          .ticket-line p {
            margin: 0;
            font-size: 14px;
            color: #4a4451;
            line-height: 1.6;
          }

          .button-container {
            margin: 32px 0;
            text-align: center;
          }

          .button {
            background-color: #0f6e56;
            color: #ffffff !important;
            padding: 14px 32px;
            border-radius: 12px;
            text-decoration: none;
            font-weight: 600;
            font-size: 15px;
            display: inline-block;
            box-shadow: 0 4px 14px rgba(15, 110, 86, 0.25);
            transition: all 0.2s;
          }

          .code-display {
            margin: 28px 0;
            text-align: center;
          }

          .code-digits {
            display: inline-flex;
            gap: 10px;
            background-color: #e4f1eb;
            padding: 16px 24px;
            border-radius: 16px;
            border: 2px dashed #0f6e56;
          }

          .code-digit {
            width: 48px;
            height: 56px;
            background-color: #ffffff;
            border-radius: 12px;
            border: 2px solid #e4f1eb;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 28px;
            font-weight: 800;
            color: #0f6e56;
            letter-spacing: 2px;
          }

          .expiry-text {
            font-size: 13px;
            color: #a8a29e;
            margin-top: 16px;
            font-style: italic;
            text-align: center;
          }

          .divider {
            height: 1px;
            background: linear-gradient(90deg, transparent, #e4f1eb, transparent);
            margin: 32px 0;
          }

          .footer {
            padding: 0 40px 40px;
            text-align: left;
            color: #a8a29e;
            font-size: 12px;
          }

          .footer-links {
            margin-bottom: 16px;
          }

          .footer-link {
            color: #78716c;
            text-decoration: none;
            margin-right: 16px;
            font-weight: 500;
            font-size: 13px;
          }

          .footer-link:hover {
            color: #0f6e56;
          }

          @media only screen and (max-width: 640px) {
            .wrapper {
              padding: 20px 0;
            }
            .container {
              border-radius: 16px;
              border-left: none;
              border-right: none;
            }
            .content, .header, .footer {
              padding-left: 24px;
              padding-right: 24px;
            }
            .title {
              font-size: 22px;
            }
          }
        </style>
      </head>
      <body>
        <div class="wrapper">
          <div class="container">
            <div class="top-banner"></div>

            <div class="header">
              <div class="logo-row">
                <a href="#" style="display: flex; align-items: center; text-decoration: none;">
                  ${logo}
                </a>
                <span class="event-badge">Live</span>
              </div>
            </div>

            <div class="content">
              <h1 class="title">${title}</h1>
              <p class="greeting">Hey ${name},</p>
              <div class="text">${content}</div>

              ${
                actionLink
                  ? `
                <div class="button-container">
                  <a href="${actionLink}" class="button">${actionText || "Let's Go"}</a>
                </div>
              `
                  : ''
              }

              ${
                code
                  ? `
                <div class="code-display">
                  <div class="code-digits">
                    ${code
                      .split('')
                      .map(d => `<div class="code-digit">${d}</div>`)
                      .join('')}
                  </div>
                </div>
              `
                  : ''
              }

              ${expiryText ? `<p class="expiry-text">${expiryText}</p>` : ''}

              <div class="divider"></div>

              <p style="font-size: 13px; color: #a8a29e; line-height: 1.5; margin: 0;">
                Didn't expect this email? No worries \u2014 just ignore it and we'll leave you alone.
              </p>
            </div>

            <div class="footer">
              <div class="footer-links">
                <a href="#" class="footer-link">Help Center</a>
                <a href="#" class="footer-link">Privacy</a>
                <a href="#" class="footer-link">Terms</a>
                <a href="#" class="footer-link">Unsubscribe</a>
              </div>
              <p style="margin-bottom: 8px;">
                \u00a9 ${new Date().getFullYear()} Techstudio Academy. All rights reserved.
              </p>
              <p style="color: #a8a29e; font-size: 12px;">
                Making tech affordable.
              </p>
            </div>
          </div>
        </div>
      </body>
    </html>
  `

export const verifyAccountTemplate = (code: string, actionLink?: string) =>
  baseLayout(
    'Your Access to Techstudio Academy',
    'Hello Admin',
    `
      Welcome to <strong>Techstudio Academy Portfolio</strong> \u2014 Thank you for joining!

      <div class="ticket-line">
        <strong style="color: #1c1917;">Enter this code to verify your email</strong>
      </div>  
    `,
    actionLink,
    'Verify & Join',
    "This code expires in 15 minutes \u2014 don't miss the show.",
    code
  )

export const resetPasswordTemplate = (resetLink: string) =>
  baseLayout(
    'Reset Your Password',
    'Hello Admin',
    `
      We received a request to reset your password.
      Click the button below to set a new one.

      <div class="ticket-line">
        <strong style="color: #1c1917;">This link is valid for 15 minutes only.</strong>
      </div>

      If you didn't request this, you can safely ignore this email.
    `,
    resetLink,
    'Reset Password',
    'This link expires in 15 minutes.',
  )
